import{_ as t,o as a,c as s,ao as o}from"./chunks/framework.DhF5Wh68.js";const k=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide.md","filePath":"guide.md","lastUpdated":null}'),n={name:"guide.md"};function i(l,e,r,d,h,p){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="Getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#Getting-started" aria-label="Permalink to &quot;Getting started {#Getting-started}&quot;">​</a></h1><h2 id="Install" tabindex="-1">Install <a class="header-anchor" href="#Install" aria-label="Permalink to &quot;Install {#Install}&quot;">​</a></h2><p>Add DocumenterSlate to your docs environment, and the plugin to <code>makedocs</code>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Documenter, DocumenterSlate</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">makedocs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; sitename </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;MyPkg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, plugins </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SlateDocs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()], pages </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">…</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span></span></code></pre></div><h2 id="Reference-a-notebook" tabindex="-1">Reference a notebook <a class="header-anchor" href="#Reference-a-notebook" aria-label="Permalink to &quot;Reference a notebook {#Reference-a-notebook}&quot;">​</a></h2><p>In any page, refer to a notebook by its file, relative to the page like a link:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```@slate ../notebooks/tour.jl</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```</span></span></code></pre></div><p>That places the whole notebook: its markdown cells become the page&#39;s own markdown (headings, cross-references and search all work), its code cells become <code>julia</code> code blocks, and each output is drawn live. Cells tagged <code>nodocs</code> are left out; <code>hidecode</code> cells show only their output.</p><p>To place part of a notebook, list the cells to include, in any order; they appear in notebook order:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```@slate ../notebooks/tour.jl</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cells = &quot;intro trace&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```</span></span></code></pre></div><p>A notebook can be split across several pages this way. A link to the notebook goes to the page that places all of it, or else to the first page that places part of it.</p><p>For one cell, add its id, and <code>show</code> to include its source:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```@slate ../notebooks/tour.jl trace</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">show = &quot;both&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```</span></span></code></pre></div><h2 id="Notebook-environments" tabindex="-1">Notebook environments <a class="header-anchor" href="#Notebook-environments" aria-label="Permalink to &quot;Notebook environments {#Notebook-environments}&quot;">​</a></h2><p>A notebook runs in the nearest <code>Project.toml</code> above it. Give your notebooks a project of their own (<code>docs/notebooks/Project.toml</code> here) holding just the packages they use, so a render doesn&#39;t load the docs toolchain into every notebook&#39;s worker.</p><h2 id="Rendering" tabindex="-1">Rendering <a class="header-anchor" href="#Rendering" aria-label="Permalink to &quot;Rendering {#Rendering}&quot;">​</a></h2><p>Before any page is built, the docs build renders each referenced notebook whose <em>bundle</em> is missing or older than the notebook. A bundle is the notebook&#39;s rendered output, kept under <code>docs/slate/&lt;name&gt;/</code>: the output of each cell, the data behind interactive controls, and the script that draws them. The notebook runs in its own <a href="https://github.com/kahliburke/KaimonSlate.jl" target="_blank" rel="noreferrer">Kaimon Slate</a> worker, through the Slate hub you already have running, or, on a machine with none, an isolated Kaimon host the build starts. A notebook that hasn&#39;t changed isn&#39;t run again.</p><p><code>docs/slate/</code> is build output: keep it out of git. <strong>Export → Docs</strong> in the notebook writes a bundle from the notebook as it stands, without a docs build.</p><h2 id="In-CI" tabindex="-1">In CI <a class="header-anchor" href="#In-CI" aria-label="Permalink to &quot;In CI {#In-CI}&quot;">​</a></h2><p>With the defaults, CI renders every notebook: the build starts an isolated Kaimon host, runs each notebook in its own worker, and writes its bundle before the pages are built. This site is built that way. Keep <code>docs/slate/</code> out of git; it is build output.</p><p>A notebook too heavy for CI (GPU work, long fits) can instead have its bundle rendered on a machine that can run it and handed to the build: build with <code>SlateDocs(render = :never, stale = :error)</code> and the build uses the bundles it is given, and fails on one that no longer matches its notebook.</p>',21)])])}const u=t(n,[["render",i]]);export{k as __pageData,u as default};
